CREATE OR REPLACE FUNCTION public.add_user_notification(p_user_id uuid, p_title text, p_body text DEFAULT NULL::text, p_link text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if p_user_id is null or p_title is null then return; end if;
  if coalesce(auth.jwt() ->> 'role', '') in ('anon', 'authenticated')
     and p_user_id is distinct from auth.uid() then
    raise exception 'add_user_notification: can only notify yourself';
  end if;
  insert into public.user_notifications (user_id, title, body, link)
  values (p_user_id, p_title, p_body, p_link);
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_search(p_query text, p_limit integer DEFAULT 6)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_pattern text;
  v_perms text[];
  v_can_customers boolean;
  v_can_leads     boolean;
  v_can_invoices  boolean;
  v_can_tasks     boolean;

  v_customers jsonb := '[]'::jsonb;
  v_leads     jsonb := '[]'::jsonb;
  v_payments  jsonb := '[]'::jsonb;
  v_tasks     jsonb := '[]'::jsonb;
begin
  -- Empty / too-short queries → empty result
  if p_query is null or length(trim(p_query)) < 1 then
    return jsonb_build_object(
      'customers', '[]'::jsonb,
      'leads',     '[]'::jsonb,
      'payments',  '[]'::jsonb,
      'tasks',     '[]'::jsonb
    );
  end if;
  v_pattern := '%' || trim(p_query) || '%';

  v_perms := coalesce(public.current_user_permissions(), '{}');
  v_can_customers := '*' = any(v_perms) or 'customers.view' = any(v_perms) or 'customers.*' = any(v_perms);
  v_can_leads     := '*' = any(v_perms) or 'leads.view'     = any(v_perms) or 'leads.*'     = any(v_perms);
  v_can_invoices  := '*' = any(v_perms) or 'invoices.view_all' = any(v_perms) or 'invoices.*' = any(v_perms) or 'payments.view_all' = any(v_perms);
  v_can_tasks     := '*' = any(v_perms) or 'tasks.view'     = any(v_perms) or 'tasks.*'     = any(v_perms);

  -- ──────── Customers (profiles) ────────
  if v_can_customers then
    select coalesce(jsonb_agg(jsonb_build_object(
      'id',       p.id,
      'name',     p.full_name,
      'email',    p.email,
      'plan',     p.plan,
      'credits',  p.credits,
      'health',   p.health_status
    ) order by p.updated_at desc nulls last), '[]'::jsonb)
    into v_customers
    from (
      select id, full_name, email, plan, credits, health_status, updated_at
        from public.profiles
       where email     ilike v_pattern
          or full_name ilike v_pattern
       order by updated_at desc nulls last
       limit p_limit
    ) p;
  end if;

  -- ──────── Leads ────────
  if v_can_leads then
    select coalesce(jsonb_agg(jsonb_build_object(
      'id',            l.id,
      'name',          l.name,
      'email',         l.email,
      'phone',         l.phone,
      'business_name', l.business_name,
      'source',        l.source,
      'status',        l.status
    ) order by l.updated_at desc nulls last), '[]'::jsonb)
    into v_leads
    from (
      select id, name, email, phone, business_name, source, status, updated_at
        from public.leads
       where name          ilike v_pattern
          or email         ilike v_pattern
          or phone         ilike v_pattern
          or business_name ilike v_pattern
          or city          ilike v_pattern
          or external_lead_id ilike v_pattern
       order by updated_at desc nulls last
       limit p_limit
    ) l;
  end if;

  -- ──────── Payments / Invoices ────────
  if v_can_invoices then
    select coalesce(jsonb_agg(jsonb_build_object(
      'id',           y.id,
      'user_id',      y.user_id,
      'plan',         y.plan,
      'amount',       y.amount,
      'status',       y.status,
      'buyer_name',   y.billing_name,
      'buyer_email',  y.billing_email,
      'razorpay_payment_id', y.razorpay_payment_id,
      'created_at',   y.created_at
    ) order by y.created_at desc), '[]'::jsonb)
    into v_payments
    from (
      select id, user_id, plan, amount, status, billing_name, billing_email,
             razorpay_payment_id, created_at
        from public.payments
       where billing_name        ilike v_pattern
          or billing_email       ilike v_pattern
          or billing_phone       ilike v_pattern
          or razorpay_payment_id ilike v_pattern
          or razorpay_order_id   ilike v_pattern
          or plan                ilike v_pattern
       order by created_at desc
       limit p_limit
    ) y;
  end if;

  -- ──────── Tasks ────────
  if v_can_tasks then
    select coalesce(jsonb_agg(jsonb_build_object(
      'id',       t.id,
      'title',    t.title,
      'status',   t.status,
      'priority', t.priority,
      'assigned_to', t.assigned_to_email,
      'due_at',   t.due_at
    ) order by t.created_at desc), '[]'::jsonb)
    into v_tasks
    from (
      select id, title, status, priority, assigned_to_email, due_at, created_at
        from public.tasks
       where title             ilike v_pattern
          or description       ilike v_pattern
          or assigned_to_email ilike v_pattern
       order by created_at desc
       limit p_limit
    ) t;
  end if;

  return jsonb_build_object(
    'customers', v_customers,
    'leads',     v_leads,
    'payments',  v_payments,
    'tasks',     v_tasks
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_unread_count()
 RETURNS integer
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_email text;
  v_perms text[];
  v_count int;
begin
  select email into v_email from auth.users where id = auth.uid();
  if v_email is null then return 0; end if;

  v_perms := coalesce(public.current_user_permissions(), '{}');

  select count(*) into v_count
    from public.admin_notifications n
    where (n.recipient_email is null
           or lower(n.recipient_email) = lower(v_email))
      and (
        n.required_permission is null
        or '*' = any(v_perms)
        or n.required_permission = any(v_perms)
        or (split_part(n.required_permission, '.', 1) || '.*') = any(v_perms)
      )
      and not exists (
        select 1 from public.admin_notification_reads r
         where r.notification_id = n.id
           and lower(r.reader_email) = lower(v_email)
      );

  return v_count;
end$function$

CREATE OR REPLACE FUNCTION public.agent_configs_list()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not (
    coalesce(auth.jwt() ->> 'role', '') not in ('anon', 'authenticated')
    or public.has_permission('agents.view')
    or public.has_permission('*')
  ) then
    raise exception 'agent_configs_list: permission denied';
  end if;

  return (
    select coalesce(jsonb_agg(jsonb_build_object(
      'agent_slug',         agent_slug,
      'display_name',       coalesce(display_name, agent_slug),
      'description',        description,
      'enabled',            enabled,
      'credits_per_gen',    credits_per_gen,
      'cost_per_gen_usd',   cost_per_generation_usd,
      'prompt_version',     prompt_version,
      'notes',              notes,
      'updated_at',         updated_at
    ) order by agent_slug), '[]'::jsonb)
    from public.agent_costs
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.ai_business_insights()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_today    date := current_date;
  v_m_start  date := date_trunc('month', current_date)::date;
  v_lm_start date := (date_trunc('month', current_date) - interval '1 month')::date;
  v_lm_end   date := date_trunc('month', current_date)::date;
  v_w_start  date := current_date - 7;
  v_insights jsonb := '[]'::jsonb;
  v_row      record;
begin
  if not (coalesce(auth.jwt() ->> 'role', '') not in ('anon', 'authenticated') or public.has_permission('dashboard.view') or public.has_permission('*')) then
    raise exception 'ai_business_insights: permission denied';
  end if;

  -- ── 1. Revenue MoM change ────────────────────────────────────
  declare
    v_rev_this  numeric;
    v_rev_last  numeric;
    v_pct       numeric;
  begin
    select coalesce(sum(amount),0) into v_rev_this from public.payments where status='paid' and created_at::date >= v_m_start;
    select coalesce(sum(amount),0) into v_rev_last from public.payments where status='paid' and created_at::date >= v_lm_start and created_at::date < v_lm_end;
    if v_rev_last > 0 then
      v_pct := round((v_rev_this - v_rev_last) * 100.0 / v_rev_last, 1);
      if abs(v_pct) >= 10 then
        v_insights := v_insights || jsonb_build_array(jsonb_build_object(
          'type',     'revenue_mom',
          'severity', case when v_pct >= 0 then 'success' else 'warning' end,
          'icon',     case when v_pct >= 0 then '📈' else '📉' end,
          'title',    'Revenue ' || case when v_pct >= 0 then 'up' else 'down' end || ' ' || abs(v_pct) || '% vs last month',
          'body',     'This month ₹' || to_char(v_rev_this,'FM999,999,999') || ' vs last month ₹' || to_char(v_rev_last,'FM999,999,999'),
          'target',   '/admin/finance'
        ));
      end if;
    end if;
  end;

  -- ── 2. Agent performance change ──────────────────────────────
  begin
    for v_row in
      with this_month as (
        select
          case when reason like '%jewellery%' then 'Jewellery AI'
               when reason like '%textile%'   then 'Textile AI'
               when reason like '%productograph%' then 'Productography AI'
               else null end as agent,
          count(*)::int as cnt
        from public.credit_transactions
        where delta < 0 and created_at::date >= v_m_start
        group by 1
      ),
      last_month as (
        select
          case when reason like '%jewellery%' then 'Jewellery AI'
               when reason like '%textile%'   then 'Textile AI'
               when reason like '%productograph%' then 'Productography AI'
               else null end as agent,
          count(*)::int as cnt
        from public.credit_transactions
        where delta < 0 and created_at::date >= v_lm_start and created_at::date < v_lm_end
        group by 1
      )
      select t.agent, t.cnt as this_cnt, coalesce(l.cnt,0) as last_cnt,
             case when coalesce(l.cnt,0) > 0 then round((t.cnt - l.cnt)*100.0/l.cnt,1) else null end as pct
      from this_month t left join last_month l using (agent)
      where t.agent is not null and abs(case when coalesce(l.cnt,0) > 0 then (t.cnt - l.cnt)*100.0/l.cnt else 0 end) >= 15
    loop
      v_insights := v_insights || jsonb_build_array(jsonb_build_object(
        'type',     'agent_usage',
        'severity', case when v_row.pct >= 0 then 'success' else 'warning' end,
        'icon',     case when v_row.pct >= 0 then '🤖' else '⚠️' end,
        'title',    v_row.agent || ' usage ' || case when v_row.pct >= 0 then 'up ' else 'down ' end || abs(v_row.pct) || '% MoM',
        'body',     'This month: ' || v_row.this_cnt || ' generations vs last: ' || v_row.last_cnt,
        'target',   '/admin/ai-operations'
      ));
    end loop;
  end;

  -- ── 3. Plan renewals due this week ───────────────────────────
  declare
    v_due int;
  begin
    select count(*) into v_due from public.profiles
    where plan_expires_at between now() and now() + interval '7 days';
    if v_due > 0 then
      v_insights := v_insights || jsonb_build_array(jsonb_build_object(
        'type',     'renewals_due',
        'severity', 'warning',
        'icon',     '⏰',
        'title',    v_due || ' plan renewal(s) due this week',
        'body',     'Follow up now to prevent churn.',
        'target',   '/admin/subscriptions'
      ));
    end if;
  end;

  -- ── 4. Failed generations spike ──────────────────────────────
  begin
    declare
      v_failed_today int;
      v_failed_week  int;
    begin
      select count(*) filter (where created_at::date = v_today)::int,
             count(*) filter (where created_at::date >= v_w_start)::int
        into v_failed_today, v_failed_week
        from public.generations where status = 'failed';
      if v_failed_today >= 5 then
        v_insights := v_insights || jsonb_build_array(jsonb_build_object(
          'type',     'failed_gens',
          'severity', 'critical',
          'icon',     '🚨',
          'title',    v_failed_today || ' AI generations failed today',
          'body',     v_failed_week || ' failures this week — check n8n and FAL API status.',
          'target',   '/admin/ai-operations'
        ));
      end if;
    exception when undefined_table then null;
    end;
  end;

  -- ── 5. Credits running low for paying users ──────────────────
  declare
    v_low_credits int;
  begin
    select count(*) into v_low_credits from public.profiles
    where credits < 50 and plan is not null and plan not in ('','free');
    if v_low_credits > 0 then
      v_insights := v_insights || jsonb_build_array(jsonb_build_object(
        'type',     'low_credits',
        'severity', 'info',
        'icon',     '💎',
        'title',    v_low_credits || ' paying customer(s) running low on credits',
        'body',     'Send a top-up reminder or upgrade nudge.',
        'target',   '/admin/customers'
      ));
    end if;
  end;

  -- ── 6. No new leads today ────────────────────────────────────
  declare
    v_leads_today int;
  begin
    select count(*) into v_leads_today from public.leads where created_at::date = v_today;
    if v_leads_today = 0 and extract(hour from now()) >= 12 then
      v_insights := v_insights || jsonb_build_array(jsonb_build_object(
        'type',     'no_leads',
        'severity', 'warning',
        'icon',     '🎯',
        'title',    'No new leads today',
        'body',     'Check Meta and Google ad campaigns.',
        'target',   '/admin/marketing'
      ));
    end if;
  end;

  -- ── 7. New signups not converted ─────────────────────────────
  declare
    v_unconverted int;
  begin
    select count(*) into v_unconverted
    from public.profiles p
    where p.created_at::date >= v_today - 3
      and (p.plan is null or p.plan in ('','free'))
      and not exists (select 1 from public.payments py where py.user_id = p.id and py.status = 'paid');
    if v_unconverted >= 5 then
      v_insights := v_insights || jsonb_build_array(jsonb_build_object(
        'type',     'unconverted_signups',
        'severity', 'info',
        'icon',     '👤',
        'title',    v_unconverted || ' free signups in last 3 days — not converted',
        'body',     'Reach out with a demo or discount.',
        'target',   '/admin/customers'
      ));
    end if;
  end;

  return jsonb_build_object(
    'generated_at', now(),
    'insights',     v_insights,
    'count',        jsonb_array_length(v_insights)
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.ai_operations_metrics()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_today   date := current_date;
  v_w_start date := current_date - 6;
  v_m_start date := date_trunc('month', current_date)::date;
  v_result  jsonb;
  v_credits jsonb := jsonb_build_object('total_consumed',0,'consumed_today',0,'consumed_week',0,'consumed_month',0);
begin
  if not (coalesce(auth.jwt() ->> 'role', '') not in ('anon', 'authenticated') or public.has_permission('ai_ops.view') or public.has_permission('*')) then
    raise exception 'ai_operations_metrics: permission denied';
  end if;

  with g as (
    select coalesce(agent_type, 'other') as agent_slug, status, created_at from public.generations
  ),
  totals as (
    select
      count(*)::int                                                          as total_all_time,
      count(*) filter (where created_at::date = v_today)::int               as total_today,
      count(*) filter (where created_at::date >= v_w_start)::int            as total_week,
      count(*) filter (where created_at::date >= v_m_start)::int            as total_month,
      count(*) filter (where status='failed')::int                          as failed_all_time,
      count(*) filter (where status='failed' and created_at::date = v_today)::int as failed_today,
      count(*) filter (where status='pending')::int                         as queued_now,
      count(*) filter (where status='completed')::int                       as completed_all_time
    from g
  ),
  by_agent as (
    select coalesce(jsonb_agg(jsonb_build_object(
      'agent_slug', agent_slug, 'total', total, 'completed', completed,
      'failed', failed, 'today', today,
      'failure_pct', case when total=0 then 0 else round(failed*100.0/total,1) end
    ) order by total desc), '[]'::jsonb) as data
    from (
      select agent_slug,
        count(*)::int                                          as total,
        count(*) filter (where status='completed')::int        as completed,
        count(*) filter (where status='failed')::int           as failed,
        count(*) filter (where created_at::date = v_today)::int as today
      from g group by agent_slug
    ) x
  ),
  recent_fails as (
    select coalesce(jsonb_agg(jsonb_build_object(
      'id', id, 'agent_slug', coalesce(agent_type,'other'), 'user_id', user_id, 'created_at', created_at
    ) order by created_at desc), '[]'::jsonb) as data
    from (select id, agent_type, user_id, created_at from public.generations
          where status='failed' and created_at::date >= current_date-7
          order by created_at desc limit 20) g2
  ),
  daily as (
    select coalesce(jsonb_agg(jsonb_build_object(
      'd', to_char(days.dd,'YYYY-MM-DD'), 'total', coalesce(cnt,0), 'failed', coalesce(failed,0)
    ) order by days.dd), '[]'::jsonb) as data
    from (select d::date as dd from generate_series((v_today-29)::timestamp, v_today::timestamp, interval '1 day') d) days
    left join (
      select created_at::date as d, count(*)::int as cnt, count(*) filter (where status='failed')::int as failed
      from public.generations where created_at::date >= v_today-29 group by 1
    ) x on x.d = days.dd
  )
  select jsonb_build_object('totals', row_to_json(t)::jsonb, 'by_agent', a.data,
    'credits', v_credits, 'recent_fails', f.data, 'daily', d.data)
  into v_result from totals t, by_agent a, recent_fails f, daily d;

  begin
    select jsonb_build_object(
      'total_consumed', coalesce(abs(sum(delta) filter (where delta<0)),0),
      'consumed_today', coalesce(abs(sum(delta) filter (where delta<0 and created_at::date=v_today)),0),
      'consumed_week',  coalesce(abs(sum(delta) filter (where delta<0 and created_at::date>=v_w_start)),0),
      'consumed_month', coalesce(abs(sum(delta) filter (where delta<0 and created_at::date>=v_m_start)),0)
    ) into v_credits from public.credit_transactions;
    v_result := jsonb_set(v_result, '{credits}', v_credits);
  exception when undefined_table then null;
  end;

  return v_result;
end;
$function$

CREATE OR REPLACE FUNCTION public.error_log_summary(p_limit integer DEFAULT 100)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not (public.has_permission('audit.view') or public.has_permission('*')) then
    raise exception 'error_log_summary: permission denied';
  end if;
  return jsonb_build_object(
    'counts', jsonb_build_object(
      'total',        (select count(*) from public.error_logs),
      'unresolved',   (select count(*) from public.error_logs where not resolved),
      'today',        (select count(*) from public.error_logs where created_at::date = current_date),
      'payment',      (select count(*) from public.error_logs where category='payment' and not resolved),
      'webhook',      (select count(*) from public.error_logs where category='webhook' and not resolved),
      'generation',   (select count(*) from public.error_logs where category='generation' and not resolved)
    ),
    'recent', (
      select coalesce(jsonb_agg(jsonb_build_object(
        'id', id, 'category', category, 'source', source,
        'message', message, 'resolved', resolved, 'created_at', created_at
      ) order by created_at desc), '[]')
      from (select * from public.error_logs order by created_at desc limit p_limit) x
    )
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.founder_command_metrics()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_today    date := current_date;
  v_m_start  date := date_trunc('month', current_date)::date;
  v_result   jsonb;
  v_goal     record;
  v_rev_month numeric;
  v_cust_month int;
  v_gens_month int;
begin
  if not (public.has_permission('*') or public.has_permission('dashboard.view')) then
    raise exception 'founder_command_metrics: permission denied';
  end if;

  select coalesce(sum(amount),0) into v_rev_month
    from public.payments where status='paid' and created_at::date >= v_m_start;

  select count(*) into v_cust_month
    from public.payments where status='paid' and created_at::date >= v_m_start;

  begin
    select count(*) into v_gens_month from public.generations where created_at::date >= v_m_start;
  exception when undefined_table then v_gens_month := 0; end;

  select * into v_goal from public.founder_goals where month = v_m_start;

  v_result := jsonb_build_object(
    'live', jsonb_build_object(
      'revenue_today',      (select coalesce(sum(amount),0) from public.payments where status='paid' and created_at::date = v_today),
      'revenue_month',      v_rev_month,
      'cash_in_bank',       (select coalesce((value)::numeric, 0) from public.system_settings where key='finance.cash_in_bank'),
      'outstanding',        (select coalesce(sum(amount),0) from public.payments where status in ('created','pending','attempted')),
      'lifetime_revenue',   (select coalesce(sum(amount),0) from public.payments where status='paid'),
      'active_subs',        (select count(*) from public.profiles where plan_expires_at > now())
    ),
    'goals', jsonb_build_object(
      'revenue_target',     coalesce(v_goal.revenue_target, 0),
      'revenue_actual',     v_rev_month,
      'revenue_pct',        case when coalesce(v_goal.revenue_target,0) > 0 then round(v_rev_month*100/v_goal.revenue_target,1) else null end,
      'customers_target',   coalesce(v_goal.customers_target, 0),
      'customers_actual',   v_cust_month,
      'customers_pct',      case when coalesce(v_goal.customers_target,0) > 0 then round(v_cust_month*100.0/v_goal.customers_target,1) else null end,
      'generations_target', coalesce(v_goal.generations_target, 0),
      'generations_actual', v_gens_month,
      'generations_pct',    case when coalesce(v_goal.generations_target,0) > 0 then round(v_gens_month*100.0/v_goal.generations_target,1) else null end
    ),
    'team', (
      select coalesce(jsonb_agg(jsonb_build_object(
        'member', member_email,
        'leads',  leads_added,
        'won',    deals_won
      ) order by deals_won desc), '[]')
      from (
        select coalesce(assigned_to,'unassigned') as member_email,
               count(*)::int as leads_added,
               count(*) filter (where status='converted')::int as deals_won
        from public.leads
        where created_at::date >= v_m_start
        group by assigned_to
      ) x
    )
  );

  return v_result;
exception when undefined_table or undefined_column then
  return jsonb_build_object('error', 'tables missing');
end;
$function$

CREATE OR REPLACE FUNCTION public.generation_log(p_limit integer DEFAULT 100, p_agent text DEFAULT NULL::text, p_status text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_rate numeric;
begin
  if not (coalesce(auth.jwt() ->> 'role', '') not in ('anon', 'authenticated') or public.has_permission('ai_ops.view') or public.has_permission('*')) then
    raise exception 'generation_log: permission denied';
  end if;
  begin select coalesce(usd_to_inr_rate,83.5) into v_rate from public.ai_cost_settings where id=1; exception when undefined_table then v_rate:=83.5; end;
  v_rate := coalesce(v_rate, 83.5);

  return (
    select coalesce(jsonb_agg(row), '[]'::jsonb) from (
      select jsonb_build_object(
        'id', g.id, 'agent', coalesce(g.agent_type,'other'), 'user_id', g.user_id,
        'email', p.email, 'status', g.status, 'created_at', g.created_at,
        'cost_usd', coalesce(c.cost_per_generation_usd, 0.04),
        'cost_inr', round(coalesce(c.cost_per_generation_usd, 0.04) * v_rate, 2)
      ) as row
      from public.generations g
      left join public.agent_costs c on c.agent_slug = g.agent_type
      left join public.profiles p on p.id = g.user_id
      where (p_agent is null or coalesce(g.agent_type,'other') = p_agent)
        and (p_status is null or g.status = p_status)
      order by g.created_at desc limit greatest(p_limit,1)
    ) sub
  );
end;
$function$

