CREATE OR REPLACE FUNCTION public.leaderboard_data(p_month date DEFAULT (date_trunc('month'::text, (CURRENT_DATE)::timestamp with time zone))::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_m_start date := date_trunc('month', p_month)::date;
  v_m_end   date := (date_trunc('month', p_month) + interval '1 month' - interval '1 day')::date;
begin
  if not (coalesce(auth.jwt() ->> 'role', '') = 'service_role' or public.has_permission('team.view') or public.has_permission('*')) then
    raise exception 'leaderboard_data: permission denied';
  end if;

  return jsonb_build_object(
    'month', v_m_start,

    'revenue_board', (
      select coalesce(jsonb_agg(jsonb_build_object(
        'rank', rnk, 'member_email', member_email, 'revenue', revenue,
        'deals', deals, 'leads_added', leads_added
      ) order by rnk), '[]'::jsonb)
      from (
        select y.*, row_number() over (order by revenue desc, deals desc) as rnk
        from (
          select coalesce(assigned_to, 'unassigned') as member_email,
                 count(*) filter (where status = 'converted')::int as deals,
                 count(*)::int as leads_added,
                 0::numeric as revenue
            from public.leads
           where created_at::date between v_m_start and v_m_end
           group by assigned_to
        ) y
      ) x
    ),

    'attendance_board', (
      select coalesce(jsonb_agg(jsonb_build_object(
        'rank', rnk, 'member_email', member_email, 'member_name', member_name,
        'days', days_present, 'total_hours', round(total_mins::numeric / 60, 1)
      ) order by rnk), '[]'::jsonb)
      from (
        select y.*, row_number() over (order by total_mins desc) as rnk
        from (
          select member_email, max(member_name) as member_name,
                 count(distinct date)::int as days_present,
                 coalesce(sum(duration_mins), 0)::int as total_mins
            from public.attendance_logs
           where date between v_m_start and v_m_end
             and check_out is not null
           group by member_email
        ) y
      ) x
    ),

    'badges', (
      select coalesce(jsonb_agg(jsonb_build_object(
        'member_email', member_email, 'badge_slug', badge_slug, 'badge_label', badge_label,
        'badge_icon', badge_icon, 'awarded_at', awarded_at
      ) order by awarded_at desc), '[]'::jsonb)
      from public.member_badges
      where month = v_m_start or month is null
    ),

    'tasks_board', (
      select coalesce(jsonb_agg(jsonb_build_object(
        'rank', rnk, 'member_email', assigned_to_email, 'done', done_count, 'pending', pending_count
      ) order by rnk), '[]'::jsonb)
      from (
        select y.*, row_number() over (order by done_count desc) as rnk
        from (
          select assigned_to_email,
                 count(*) filter (where status = 'done')::int  as done_count,
                 count(*) filter (where status <> 'done')::int as pending_count
            from public.tasks
           where created_at::date between v_m_start and v_m_end
             and assigned_to_email is not null
           group by assigned_to_email
        ) y
      ) x
    )
  );
end;
$function$

